"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"
import { useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { formatDashboardValue, shareOf, type DashboardFormat } from "@/lib/dashboard-format"

export type BreakdownSegment = {
  id: string
  label: string
  value: number
}

export type BreakdownBarClassNames = {
  root?: string
  total?: string
  track?: string
  legend?: string
}

export type BreakdownBarProps = {
  total: number
  segments: readonly BreakdownSegment[]
  label?: string
  format?: DashboardFormat
  locale?: string
  currency?: string
  /** legend is the default list. pipeline draws gapped stages with counts underneath. */
  variant?: "legend" | "pipeline"
  /** Segment index drawn in the accent. The last segment stays inverted. */
  emphasis?: number
  heading?: string
  caption?: string
  action?: { label: string; onSelect: () => void }
  className?: string
  classNames?: BreakdownBarClassNames
}

const segmentClass = ["bg-primary", "bg-chart-2", "bg-chart-3", "bg-chart-4", "bg-chart-5"]

export function BreakdownBar({
  total,
  segments,
  label = "Breakdown",
  format = "currency",
  locale = "en-US",
  currency = "USD",
  variant = "legend",
  emphasis,
  heading,
  caption,
  action,
  className,
  classNames,
}: BreakdownBarProps) {
  const reduced = useReducedMotion() ?? false
  const [active, setActive] = React.useState<string | null>(null)
  const sum = segments.reduce((acc, segment) => acc + Math.max(0, segment.value), 0)
  const basis = sum > 0 ? sum : Math.max(total, 0)
  const summary = segments
    .map((segment) => `${segment.label} ${formatDashboardValue(segment.value, format, locale, currency)}`)
    .join(", ")

  if (variant === "pipeline") {
    return (
      <div data-slot="breakdown-bar" data-variant="pipeline" className={cn("flex min-w-0 flex-col gap-3", className, classNames?.root)}>
        <div className="flex flex-wrap items-center justify-between gap-2">
          <p className="text-sm font-medium">{heading ?? label}</p>
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            {caption ? <span>{caption}</span> : null}
            {action ? (
              <button type="button" className="font-medium text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none" onClick={action.onSelect}>
                {action.label}
              </button>
            ) : null}
          </div>
        </div>
        <div role="img" aria-label={`${label}: ${summary}`} className={cn("flex h-3 gap-1", classNames?.track)}>
          {segments.map((segment, index) => {
            const share = shareOf(Math.max(0, segment.value), basis)
            const last = index === segments.length - 1
            const hot = emphasis === index
            return (
              <span
                key={segment.id}
                data-segment={segment.id}
                className="h-full min-w-1 origin-left"
                style={{ width: `${Math.max(share * 100, share > 0 ? 6 : 0)}%` }}
              >
                <span
                  className={cn(
                    "block h-full rounded-full motion-safe:animate-in motion-safe:slide-in-from-left-2",
                    reduced && "animate-none",
                    hot ? "bg-primary" : last ? "bg-foreground" : "bg-muted-foreground/25",
                  )}
                />
              </span>
            )
          })}
        </div>
        <div className="flex gap-1">
          {segments.map((segment) => {
            const share = shareOf(Math.max(0, segment.value), basis)
            return (
              <div key={segment.id} className="min-w-0" style={{ width: `${Math.max(share * 100, share > 0 ? 6 : 0)}%` }}>
                <p className="font-mono text-sm tabular-nums">{formatDashboardValue(segment.value, "number", locale)}</p>
                <p className="truncate text-[10px] text-muted-foreground">{segment.label}</p>
              </div>
            )
          })}
        </div>
      </div>
    )
  }

  return (
    <div data-slot="breakdown-bar" className={cn("flex min-w-0 flex-col gap-3", className, classNames?.root)}>
      <p className={cn("text-4xl font-normal tabular-nums tracking-tight break-words", classNames?.total)}>
        {formatDashboardValue(total, format, locale, currency)}
      </p>
      <div
        data-slot="breakdown-track"
        role="img"
        aria-label={`${label}: ${summary}`}
        className={cn("flex h-2.5 gap-0.5 overflow-hidden rounded-full bg-muted", classNames?.track)}
      >
        {segments.map((segment, index) => {
          const share = shareOf(Math.max(0, segment.value), basis)
          const dim = active != null && active !== segment.id
          return (
            <span
              key={segment.id}
              data-segment={segment.id}
              data-dim={dim ? "true" : undefined}
              className={cn("h-full min-w-1 rounded-full transition-opacity motion-reduce:transition-none data-[dim=true]:opacity-40", segmentClass[index % segmentClass.length])}
              style={{ width: `${Math.max(share * 100, share > 0 ? 4 : 0)}%` }}
            />
          )
        })}
      </div>
      <ul className={cn("flex flex-col", classNames?.legend)}>
        {segments.map((segment, index) => {
          const share = shareOf(Math.max(0, segment.value), basis)
          const dim = active != null && active !== segment.id
          return (
            <li key={segment.id}>
              <button
                type="button"
                className="flex w-full items-center gap-2 rounded-md py-1.5 text-start text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                aria-pressed={active === segment.id}
                onMouseEnter={() => setActive(segment.id)}
                onMouseLeave={() => setActive(null)}
                onFocus={() => setActive(segment.id)}
                onBlur={() => setActive(null)}
              >
                <span className={cn("size-2 shrink-0 rounded-full", segmentClass[index % segmentClass.length])} aria-hidden />
                <span className={cn("min-w-0 flex-1 truncate", dim && "opacity-40")}>{segment.label}</span>
                <span className="shrink-0 tabular-nums">
                  {formatDashboardValue(segment.value, format, locale, currency)}
                  <span className="ms-2 text-muted-foreground">{formatDashboardValue(share, "percent", locale)}</span>
                </span>
              </button>
            </li>
          )
        })}
      </ul>
    </div>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"
import { ChevronLeft, MoreHorizontal } from "lucide-react"

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { cn } from "@/lib/utils"
import { joinMeta } from "@/lib/dashboard-format"
import { PriorityBadge, type PriorityLevel } from "@/components/ui/priority-badge"

export type RecordCrumb = { label: string; href?: string; onSelect?: () => void }

export type RecordPerson = { name: string; src?: string }

export type RecordAction = { id: string; label: string; onSelect: () => void }

export type RecordHeaderClassNames = {
  root?: string
  title?: string
  meta?: string
  actions?: string
}

export type RecordHeaderProps = {
  crumbs?: readonly RecordCrumb[]
  title: string
  headingLevel?: 1 | 2 | 3
  status?: string
  meta?: readonly string[]
  people?: readonly RecordPerson[]
  priority?: PriorityLevel
  priorityLabel?: string
  statusDot?: string
  statusTone?: "neutral" | "accent" | "info" | "warning"
  onBack?: () => void
  backLabel?: string
  leading?: React.ReactNode
  primary?: React.ReactNode
  secondary?: readonly RecordAction[]
  menu?: readonly RecordAction[]
  collapseActions?: boolean
  aside?: React.ReactNode
  className?: string
  classNames?: RecordHeaderClassNames
}

function initials(name: string) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
}

function CrumbLink({ crumb }: { crumb: RecordCrumb }) {
  if (crumb.href) {
    return (
      <BreadcrumbLink
        href={crumb.href}
        onClick={(event) => {
          if (!crumb.onSelect) return
          event.preventDefault()
          crumb.onSelect()
        }}
      >
        {crumb.label}
      </BreadcrumbLink>
    )
  }
  return (
    <button type="button" className="hover:text-foreground" onClick={crumb.onSelect}>
      {crumb.label}
    </button>
  )
}

export function RecordHeader({
  crumbs = [],
  title,
  headingLevel = 1,
  status,
  meta = [],
  people = [],
  priority,
  priorityLabel,
  statusDot,
  statusTone = "info",
  onBack,
  backLabel = "Back",
  leading,
  primary,
  secondary = [],
  menu = [],
  collapseActions = true,
  aside,
  className,
  classNames,
}: RecordHeaderProps) {
  const rootRef = React.useRef<HTMLElement>(null)
  const [narrow, setNarrow] = React.useState(false)
  React.useEffect(() => {
    const node = rootRef.current
    if (!node || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver((entries) => {
      setNarrow((entries[0]?.contentRect.width ?? 0) < 400)
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [])
  const Heading = `h${headingLevel}` as "h1" | "h2" | "h3"
  const middle = crumbs.length > 2 ? crumbs.slice(1, -1) : []
  const foldSecondary = collapseActions && narrow
  const menuActions = [...menu, ...(foldSecondary ? secondary : [])]
  return (
    <header ref={rootRef} data-slot="record-header" className={cn("@container min-w-0", className, classNames?.root)}>
      {crumbs.length ? (
        <Breadcrumb>
          <BreadcrumbList>
            <BreadcrumbItem>
              {crumbs[0]?.href || crumbs[0]?.onSelect ? <CrumbLink crumb={crumbs[0]} /> : <span>{crumbs[0]?.label}</span>}
            </BreadcrumbItem>
            {middle.length ? (
              <>
                <BreadcrumbSeparator />
                <BreadcrumbItem className="@max-[30rem]:hidden">
                  <span className="inline-flex flex-wrap items-center gap-1.5">
                    {middle.map((crumb) => (
                      <span key={crumb.label} className="inline-flex items-center gap-1.5">
                        <CrumbLink crumb={crumb} />
                        <span aria-hidden>/</span>
                      </span>
                    ))}
                  </span>
                </BreadcrumbItem>
                <BreadcrumbItem className="hidden @max-[30rem]:inline-flex">
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button type="button" variant="ghost" size="icon-sm" aria-label="More breadcrumbs">
                        <MoreHorizontal />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent>
                      {middle.map((crumb) => (
                        <DropdownMenuItem key={crumb.label} onSelect={() => crumb.onSelect?.()}>
                          {crumb.label}
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuContent>
                  </DropdownMenu>
                </BreadcrumbItem>
              </>
            ) : null}
            {crumbs.length > 1 ? (
              <>
                <BreadcrumbSeparator />
                <BreadcrumbItem>
                  <BreadcrumbPage className="break-words">{crumbs[crumbs.length - 1]?.label}</BreadcrumbPage>
                </BreadcrumbItem>
              </>
            ) : null}
          </BreadcrumbList>
        </Breadcrumb>
      ) : null}
      <div className="mt-2 flex flex-wrap items-start justify-between gap-3">
        {onBack ? (
          <Button type="button" size="icon" variant="ghost" className="rounded-full" aria-label={backLabel} onClick={onBack}>
            <ChevronLeft />
          </Button>
        ) : null}
        {leading}
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <Heading className={cn("m-0 text-3xl font-normal tracking-tight break-words", classNames?.title)}>{title}</Heading>
            {status ? (
              <span
                data-tone={statusTone}
                className={cn(
                  "inline-flex h-6 items-center gap-1 rounded-full px-2 text-xs",
                  statusTone === "accent" && "bg-primary/15",
                  statusTone === "warning" && "bg-chart-4/15",
                  statusTone === "neutral" && "bg-muted",
                  statusTone === "info" && "bg-chart-2/20",
                )}
              >
                {statusTone === "info" ? <span aria-hidden className="size-1.5 rounded-full bg-chart-2" /> : null}
                {status}
              </span>
            ) : null}
          </div>
          {meta.length ? <p className={cn("mt-1 text-sm text-muted-foreground break-words", classNames?.meta)}>{joinMeta([...meta])}</p> : null}
          {people.length || priority || statusDot ? (
            <div className="mt-2 flex flex-wrap items-center gap-2">
              {people.length ? (
                <span className="inline-flex items-center">
                  {people.map((person, index) => (
                    <Avatar key={person.name} size="sm" className={cn(index > 0 && "-ms-2 ring-2 ring-background")}>
                      {person.src ? <AvatarImage src={person.src} alt="" /> : null}
                      <AvatarFallback>{initials(person.name)}</AvatarFallback>
                    </Avatar>
                  ))}
                  <span className="ms-2 text-xs text-muted-foreground">{people.map((person) => person.name).join(", ")}</span>
                </span>
              ) : null}
              {priority ? <PriorityBadge level={priority} label={priorityLabel} /> : null}
              {statusDot ? (
                <span className="inline-flex items-center gap-1 text-xs text-muted-foreground">
                  <span className="size-2 rounded-full bg-chart-2" aria-hidden />
                  {statusDot}
                </span>
              ) : null}
            </div>
          ) : null}
        </div>
        <div className={cn("flex flex-wrap items-center gap-2", classNames?.actions)}>
          {aside}
          {menuActions.length ? (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button type="button" variant="ghost" size="icon" className="rounded-full" aria-label="More actions">
                  <MoreHorizontal />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                {menuActions.map((action) => (
                  <DropdownMenuItem key={action.id} onSelect={() => action.onSelect()}>
                    {action.label}
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          ) : null}
          {foldSecondary ? null : (
            <div className="flex flex-wrap gap-2">
              {secondary.map((action) => (
                <Button key={action.id} type="button" variant="secondary" className="rounded-full bg-muted" onClick={action.onSelect}>
                  {action.label}
                </Button>
              ))}
            </div>
          )}
          {primary}
        </div>
      </div>
    </header>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"
import { Calendar, Check } from "lucide-react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { formatDashboardDate, joinMeta } from "@/lib/dashboard-format"

export type RecordTimelineStatus = "default" | "alert" | "done" | "pending"

export type RecordTimelineEvent = {
  id: string
  title: string
  date: string | number | Date
  description?: string
  meta?: string
  status?: RecordTimelineStatus
  chips?: readonly { id: string; label: string; tone?: "neutral" | "accent" }[]
}

export type RecordTimelineClassNames = {
  root?: string
  item?: string
  title?: string
  description?: string
}

export type RecordTimelineProps = {
  events: readonly RecordTimelineEvent[]
  label?: string
  context?: string
  rangeLabel?: string
  order?: "asc" | "desc"
  locale?: string
  collapseAfter?: number
  moreLabel?: (hidden: number) => string
  onSelect?: (event: RecordTimelineEvent) => void
  filters?: readonly { id: string; label: string }[]
  filter?: string
  onFilterChange?: (id: string) => void
  className?: string
  classNames?: RecordTimelineClassNames
}

function timeValue(value: string | number | Date) {
  const date = value instanceof Date ? value : new Date(value)
  const ms = date.getTime()
  return Number.isNaN(ms) ? 0 : ms
}

export function RecordTimeline({
  events,
  label = "Record timeline",
  context,
  rangeLabel,
  order = "asc",
  locale = "en-US",
  collapseAfter,
  moreLabel = (hidden) => `Show ${hidden} earlier`,
  onSelect,
  filters = [],
  filter,
  onFilterChange,
  className,
  classNames,
}: RecordTimelineProps) {
  const [expanded, setExpanded] = React.useState(false)
  const sorted = [...events].sort((a, b) => timeValue(a.date) - timeValue(b.date))
  const ordered = order === "desc" ? sorted.reverse() : sorted
  const hidden = collapseAfter != null && !expanded ? Math.max(0, ordered.length - collapseAfter) : 0
  const visible = hidden > 0 ? (order === "asc" ? ordered.slice(hidden) : ordered.slice(0, collapseAfter)) : ordered

  return (
    <div data-slot="record-timeline" className={cn("min-w-0", className, classNames?.root)}>
      {filters.length ? (
        <div role="group" aria-label={label} className="mb-3 inline-flex rounded-full bg-muted p-0.5">
          {filters.map((item) => {
            const selected = (filter ?? filters[0]?.id) === item.id
            return (
              <button
                key={item.id}
                type="button"
                aria-pressed={selected}
                className={cn("rounded-full px-3 py-1 text-xs", selected ? "bg-foreground text-background" : "text-muted-foreground")}
                onClick={() => onFilterChange?.(item.id)}
              >
                {item.label}
              </button>
            )
          })}
        </div>
      ) : null}
      {context || rangeLabel ? (
        <div className="mb-3 flex flex-wrap items-center justify-between gap-2 text-xs text-muted-foreground">
          {context ? <p className="min-w-0 break-words">{context}</p> : <span />}
          {rangeLabel ? (
            <span className="inline-flex h-6 items-center gap-1 rounded-full bg-muted px-2">
              <Calendar className="size-3.5" aria-hidden />
              {rangeLabel}
            </span>
          ) : null}
        </div>
      ) : null}
      {hidden > 0 && order === "asc" ? (
        <Button type="button" variant="ghost" size="sm" className="mb-2" onClick={() => setExpanded(true)}>
          {moreLabel(hidden)}
        </Button>
      ) : null}
      <ol aria-label={label} className="flex flex-col">
        {visible.map((event, index) => {
          const status = event.status ?? "default"
          const when = formatDashboardDate(event.date, locale, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" })
          const iso = new Date(event.date)
          const dateTime = Number.isNaN(iso.getTime()) ? undefined : iso.toISOString()
          const statusText = status === "default" ? "" : status
          return (
            <li key={event.id} className={cn("relative flex gap-3 pb-4 last:pb-0", classNames?.item)}>
              {index < visible.length - 1 ? <span className="absolute start-[7px] top-4 bottom-0 w-px bg-border" aria-hidden /> : null}
              <span
                data-status={status}
                className={cn(
                  "relative z-[1] mt-1 grid size-4 shrink-0 place-items-center rounded-full",
                  status === "default" && "border border-muted-foreground/40 bg-card",
                  status === "alert" && "bg-destructive",
                  status === "done" && "bg-chart-2 text-foreground",
                  status === "pending" && "border border-dashed border-muted-foreground bg-card",
                )}
                aria-hidden
              >
                {status === "done" ? <Check className="size-2.5" /> : null}
              </span>
              <div className="min-w-0 flex-1">
                {onSelect ? (
                  <button type="button" className="w-full rounded-md text-start focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring" onClick={() => onSelect(event)}>
                    <EventCopy event={event} when={when} dateTime={dateTime} statusText={statusText} classNames={classNames} />
                  </button>
                ) : (
                  <EventCopy event={event} when={when} dateTime={dateTime} statusText={statusText} classNames={classNames} />
                )}
              </div>
            </li>
          )
        })}
      </ol>
    </div>
  )
}

function EventCopy({
  event,
  when,
  dateTime,
  statusText,
  classNames,
}: {
  event: RecordTimelineEvent
  when: string
  dateTime?: string
  statusText: string
  classNames?: RecordTimelineClassNames
}) {
  return (
    <>
      <span className="flex items-baseline justify-between gap-3">
        <span className={cn("text-sm font-medium break-words", classNames?.title)}>
          {event.title}
          {statusText ? <span className="sr-only"> — {statusText}</span> : null}
        </span>
        <time dateTime={dateTime} className="shrink-0 text-xs text-muted-foreground">
          {when}
        </time>
      </span>
      {event.description ? <p className={cn("mt-0.5 text-sm text-muted-foreground", classNames?.description)}>{event.description}</p> : null}
      {event.meta ? <p className="mt-0.5 text-xs text-muted-foreground">{joinMeta(event.meta.split("·").map((part) => part.trim()))}</p> : null}
      {event.chips?.length ? (
        <span className="mt-1 flex flex-wrap gap-1">
          {event.chips.map((chip) => (
            <span
              key={chip.id}
              className={cn(
                "inline-flex h-5 items-center rounded-full px-2 font-mono text-[10px]",
                chip.tone === "accent" ? "bg-primary/15" : "bg-muted",
              )}
            >
              {chip.label}
            </span>
          ))}
        </span>
      ) : null}
    </>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"
import { Check, Sparkles } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { cn } from "@/lib/utils"

export type SuggestedChoice = {
  id: string
  label: string
  description?: string
  suggested?: boolean
}

export type SuggestedChoiceField = {
  id: string
  label: string
  value?: string
  placeholder?: string
  options: readonly { value: string; label: string }[]
}

export type SuggestedChoiceDialogProps = {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  title: string
  subtitle?: string
  hint?: string
  options: readonly SuggestedChoice[]
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
  fields?: readonly SuggestedChoiceField[]
  onFieldChange?: (id: string, value: string) => void
  onConfirm?: (choiceId: string, fields: Record<string, string>) => void
  confirmLabel?: string
  cancelLabel?: string
  suggestedLabel?: string
  busy?: boolean
  className?: string
}

export function SuggestedChoiceDialog({
  open,
  defaultOpen = false,
  onOpenChange,
  title,
  subtitle,
  hint,
  options,
  value,
  defaultValue,
  onValueChange,
  fields = [],
  onFieldChange,
  onConfirm,
  confirmLabel = "Confirm",
  cancelLabel = "Cancel",
  suggestedLabel = "Suggested",
  busy = false,
  className,
}: SuggestedChoiceDialogProps) {
  const suggested = options.find((option) => option.suggested)?.id ?? options[0]?.id ?? ""
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const [internalValue, setInternalValue] = React.useState(defaultValue ?? suggested)
  const [internalFields, setInternalFields] = React.useState<Record<string, string>>(() =>
    Object.fromEntries(fields.map((field) => [field.id, field.value ?? ""])),
  )
  const shown = open ?? internalOpen
  const selected = value ?? internalValue
  const fieldValues = Object.fromEntries(fields.map((field) => [field.id, field.value ?? internalFields[field.id] ?? ""]))
  const missing = fields.some((field) => !fieldValues[field.id])
  const groupName = React.useId()

  function setOpen(next: boolean) {
    if (open === undefined) setInternalOpen(next)
    onOpenChange?.(next)
  }

  function select(id: string) {
    if (value === undefined) setInternalValue(id)
    onValueChange?.(id)
  }

  function changeField(id: string, next: string) {
    setInternalFields((current) => ({ ...current, [id]: next }))
    onFieldChange?.(id, next)
  }

  return (
    <Dialog open={shown} onOpenChange={setOpen}>
      <DialogContent className={cn("@container max-w-lg", className)}>
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          {subtitle ? <DialogDescription>{subtitle}</DialogDescription> : <DialogDescription className="sr-only">{title}</DialogDescription>}
        </DialogHeader>
        {hint ? (
          <p className="flex items-start gap-2 rounded-lg bg-chart-3/15 px-3 py-2 text-sm">
            <Sparkles className="mt-0.5 size-4 shrink-0" aria-hidden />
            <span>{hint}</span>
          </p>
        ) : null}
        <div role="radiogroup" aria-label={title} className="flex flex-col gap-1 rounded-xl border border-border p-1">
          {options.map((option) => {
            const checked = option.id === selected
            return (
              <label
                key={option.id}
                className={cn(
                  "flex cursor-pointer items-start gap-3 rounded-lg px-3 py-2 text-sm",
                  checked && "bg-muted",
                )}
              >
                <input
                  type="radio"
                  name={groupName}
                  className="mt-1 accent-primary"
                  value={option.id}
                  checked={checked}
                  autoFocus={checked}
                  onChange={() => select(option.id)}
                />
                <span className="min-w-0 flex-1">
                  <span className="flex items-center justify-between gap-2">
                    <span className="font-medium break-words">{option.label}</span>
                    {option.suggested ? (
                      <span className="shrink-0 rounded-full bg-chart-3/15 px-2 py-0.5 text-xs">{suggestedLabel}</span>
                    ) : null}
                  </span>
                  {option.description ? <span className="mt-0.5 block text-xs text-muted-foreground">{option.description}</span> : null}
                </span>
              </label>
            )
          })}
        </div>
        {fields.length ? (
          <div className="grid gap-3 @min-[26rem]:grid-cols-2">
            {fields.map((field) => (
              <label key={field.id} className="flex min-w-0 flex-col gap-1 text-sm">
                <span>{field.label}</span>
                <select
                  className="h-9 rounded-md border border-input bg-background px-2 text-sm"
                  value={fieldValues[field.id] ?? ""}
                  onChange={(event) => changeField(field.id, event.target.value)}
                >
                  <option value="">{field.placeholder ?? "Choose"}</option>
                  {field.options.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </label>
            ))}
          </div>
        ) : null}
        <DialogFooter>
          <Button type="button" variant="secondary" className="rounded-full" onClick={() => setOpen(false)}>
            {cancelLabel}
          </Button>
          <Button
            type="button"
            className="rounded-full"
            disabled={busy || !selected || missing}
            onClick={() => {
              if (!selected) return
              onConfirm?.(selected, fieldValues)
            }}
          >
            {busy ? <span className="size-3.5 animate-spin rounded-full border-2 border-current border-r-transparent motion-reduce:animate-none" aria-hidden /> : <Check data-icon="inline-start" />}
            {confirmLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

/** Adapted from Arc UI (MIT). */

import { createContext, useCallback, useContext, useEffect, useLayoutEffect, useRef, useState, useSyncExternalStore } from "react"
import type { FocusEvent, KeyboardEvent, MouseEvent, PointerEvent as ReactPointerEvent, ReactNode } from "react"
import { AnimatePresence, animate, motion, useIsPresent, useMotionValue, usePresence, useReducedMotion, useTransform } from "motion/react"
import type { HTMLMotionProps, MotionProps, TargetAndTransition, Transition } from "motion/react"
import { CircleCheck, CircleX, Info, TriangleAlert, X } from "lucide-react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type ToastType = "success" | "info" | "warning" | "error" | "loading"

export type ToastAppearance = "default" | "undo"

export interface ToastAction {
  label: string
  /** Runs the action. The toast closes afterwards unless the handler updates it, so an Undo can morph the toast into its result. */
  onClick: (id: string) => void
}

export interface ToastOptions {
  /** Reuse an id to update a toast in place instead of stacking a new one. */
  id?: string
  type?: ToastType
  /** Dark pill with an undo action. Pauses with the rest of the stack and lasts 6 seconds unless duration is set. */
  appearance?: ToastAppearance
  title: string
  description?: string
  action?: ToastAction
  /** Milliseconds before the toast closes itself. Defaults by type; loading toasts wait for an update. Pass Infinity to keep it until closed. */
  duration?: number
}

export interface ToastStackApi {
  /** Shows a toast and returns its id. */
  toast: (options: ToastOptions) => string
  /** Morphs a toast in place: icon, copy, and height animate to the new content and its timer restarts. Pass `action: undefined` to remove the action. */
  update: (id: string, patch: Partial<Omit<ToastOptions, "id">>) => void
  /** Dismisses one toast, or every toast when called without an id. */
  dismiss: (id?: string) => void
}

export interface ToastStackProviderProps {
  children: ReactNode
  /** Base lifetime in milliseconds. Warnings and errors stay 1.6 times longer. */
  duration?: number
  /** Oldest toasts beyond this count are dropped from the queue. */
  limit?: number
}

/**
 * The viewport for a toast stack. Render it once inside a `ToastStackProvider` and call `useToastStack()` anywhere below.
 * Use it for short, non-blocking results of what someone just did: new toasts rise from the bottom edge, older ones tuck behind,
 * and hovering or focusing the stack fans it out into a list. Toasts pause while the stack is open or the tab is hidden, and swipe right to dismiss.
 */
export interface ToastStackProps {
  /** Accessible name of the notification region. */
  label?: string
  position?: "bottom-right" | "bottom-center" | "bottom-left"
  /** Pins the stack inside the nearest positioned ancestor instead of the window, for panels and previews. */
  contained?: boolean
  /** How many toasts show at once. Older ones wait behind and return as the front ones close. */
  visibleToasts?: number
  /** Alt+T moves focus into the stack. */
  hotkey?: boolean
  className?: string
  classNames?: ToastStackClassNames
}

export type ToastStackClassNames = {
  root?: string
  list?: string
  item?: string
  card?: string
  title?: string
  description?: string
  action?: string
  close?: string
}

type ToastRecord = { id: string; type: ToastType; appearance: ToastAppearance; title: string; description?: string; action?: ToastAction; duration: number; seq: number; version: number }
type ToastStore = ToastStackApi & { subscribe: (listener: () => void) => () => void; getSnapshot: () => ToastRecord[]; runAction: (id: string) => void }
type Target = { y: number; scale: number; height: number; opacity: number; content: number }

const PEEK = 14
const GAP = 12
const STEP = 0.05
const BORDER = 2
const SWIPE_FADE = 280
const EMPTY: ToastRecord[] = []
const typeLabels: Record<ToastType, string> = { success: "Success", info: "Info", warning: "Warning", error: "Error", loading: "In progress" }
const icons = { success: CircleCheck, info: Info, warning: TriangleAlert, error: CircleX }
const typeColor: Record<ToastType, string> = {
  success: "text-[color:var(--chart-2)]",
  info: "text-primary",
  warning: "text-[color:var(--chart-4)]",
  error: "text-destructive",
  loading: "text-muted-foreground",
}

const standard = [...motionPresets.ease.standard] as [number, number, number, number]
const enterEase = [...motionPresets.ease.enter] as [number, number, number, number]
const fade: Transition = { duration: motionPresets.duration.fast, ease: standard }
const enterFade: Transition = { duration: motionPresets.duration.standard, ease: enterEase }
const reducedFade: Transition = { duration: 0.15, ease: standard }
const exitFast: Transition = { duration: motionPresets.duration.fast, ease: standard }
const textIn: TargetAndTransition = { opacity: 0, y: "0.3em", filter: `blur(${motionPresets.blur.soft}px)` }
const textOut: TargetAndTransition = { opacity: 0, y: "-0.3em", filter: `blur(${motionPresets.blur.subtle}px)`, transition: exitFast }
const iconIn: TargetAndTransition = { opacity: 0, scale: 0.6, filter: `blur(${motionPresets.blur.subtle}px)` }
const shown: TargetAndTransition = { opacity: 1, y: "0em", scale: 1, filter: "blur(0px)" }
const fadeOnly: MotionProps = { initial: { opacity: 0 }, animate: { opacity: 1 }, exit: { opacity: 0, transition: reducedFade }, transition: reducedFade }
const textSwap: MotionProps = { initial: textIn, animate: shown, exit: textOut, transition: { duration: 0.22, ease: enterEase } }
const iconSwap: MotionProps = { initial: iconIn, animate: shown, exit: { ...iconIn, transition: exitFast }, transition: { ...motionPresets.spring.snappy, opacity: fade, filter: fade } }

const durationFor = (type: ToastType, base: number) => (type === "loading" ? Infinity : type === "warning" || type === "error" ? base * 1.6 : base)
const project = (velocity: number) => (velocity / 1000) * (0.99 / (1 - 0.99))
const rubberBand = (distance: number, dimension: number) => (1 - 1 / ((distance * 0.55) / dimension + 1)) * dimension
const subscribeVisibility = (listener: () => void) => {
  document.addEventListener("visibilitychange", listener)
  return () => document.removeEventListener("visibilitychange", listener)
}
const getServerSnapshot = () => EMPTY
const focusVisible = (element: Element) => {
  try {
    return element.matches(":focus-visible")
  } catch {
    return true
  }
}

function layoutStack(toasts: ToastRecord[], heights: Record<string, number>, expanded: boolean, visibleToasts: number) {
  const front = toasts.length ? heights[toasts[0].id] ?? 0 : 0
  const tops = toasts.reduce<number[]>((sum, _item, index) => [...sum, sum[index] + (index < visibleToasts ? (heights[toasts[index].id] ?? 0) + GAP : 0)], [0])
  const targets = toasts.map((item, index): Target => {
    const visible = index < visibleToasts
    const depth = Math.min(index, visibleToasts)
    return expanded
      ? { y: -tops[index], scale: 1, height: heights[item.id] ?? 0, opacity: visible ? 1 : 0, content: 1 }
      : { y: -PEEK * depth, scale: 1 - STEP * depth, height: index === 0 ? heights[item.id] ?? 0 : front, opacity: visible ? 1 : 0, content: index === 0 ? 1 : 0 }
  })
  const listHeight = !toasts.length ? 0 : expanded ? tops[toasts.length] - GAP : front + PEEK * (Math.min(toasts.length, visibleToasts) - 1)
  return { targets, listHeight }
}

function createToastStore(base: number, limit: number): ToastStore {
  let toasts: ToastRecord[] = []
  let seq = 0
  const listeners = new Set<() => void>()
  const commit = (next: ToastRecord[]) => {
    toasts = next
    listeners.forEach((listener) => listener())
  }
  const update: ToastStackApi["update"] = (id, patch) => {
    const found = toasts.find((item) => item.id === id)
    if (!found) return
    const type = patch.type ?? found.type
    const appearance = patch.appearance ?? found.appearance
    const record: ToastRecord = {
      ...found,
      ...patch,
      type,
      appearance,
      duration: patch.duration ?? (appearance === "undo" ? 6000 : durationFor(type, base)),
      version: found.version + 1,
    }
    commit(toasts.map((item) => (item.id === id ? record : item)))
  }
  const toast: ToastStackApi["toast"] = ({ id, ...options }) => {
    if (id && toasts.some((item) => item.id === id)) {
      update(id, options)
      return id
    }
    const type = options.type ?? "info"
    const appearance = options.appearance ?? "default"
    seq += 1
    const record: ToastRecord = {
      ...options,
      id: id ?? `toast-${seq}`,
      type,
      appearance,
      duration: options.duration ?? (appearance === "undo" ? 6000 : durationFor(type, base)),
      seq,
      version: 0,
    }
    commit([record, ...toasts].slice(0, limit))
    return record.id
  }
  const dismiss: ToastStackApi["dismiss"] = (id) => {
    if (id === undefined) {
      if (toasts.length) commit([])
      return
    }
    if (toasts.some((item) => item.id === id)) commit(toasts.filter((item) => item.id !== id))
  }
  const runAction = (id: string) => {
    const found = toasts.find((item) => item.id === id)
    if (!found?.action) return
    found.action.onClick(id)
    if (toasts.find((item) => item.id === id)?.version === found.version) dismiss(id)
  }
  return {
    toast,
    update,
    dismiss,
    runAction,
    subscribe: (listener) => {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    getSnapshot: () => toasts,
  }
}

const ToastStackContext = createContext<ToastStore | null>(null)

function useStore() {
  const store = useContext(ToastStackContext)
  if (!store) throw new Error("Render toast stack consumers inside <ToastStackProvider>.")
  return store
}

/** Scopes a toast queue to its subtree, so two stacks on one page never share toasts. */
export function ToastStackProvider({ children, duration = 5000, limit = 12 }: ToastStackProviderProps) {
  const [store] = useState(() => createToastStore(duration, limit))
  return <ToastStackContext.Provider value={store}>{children}</ToastStackContext.Provider>
}

/** Shows, updates, and dismisses toasts from anywhere inside the provider. `count` is how many toasts are queued. */
export function useToastStack(): ToastStackApi & { count: number } {
  const store = useStore()
  const count = useSyncExternalStore(store.subscribe, () => store.getSnapshot().length, () => 0)
  return { toast: store.toast, update: store.update, dismiss: store.dismiss, count }
}

function Swap(props: HTMLMotionProps<"span">) {
  const present = useIsPresent()
  return <motion.span {...props} aria-hidden={present ? props["aria-hidden"] : true} />
}

type Gesture = { pointerId: number; startX: number; startY: number; origin: number; active: boolean; samples: { t: number; x: number }[] }

interface ToastItemProps {
  toast: ToastRecord
  target: Target
  expanded: boolean
  front: boolean
  hidden: boolean
  paused: boolean
  reduce: boolean
  store: ToastStore
  classNames?: ToastStackClassNames
  onMeasure: (id: string, height: number) => void
  onDragChange: (dragging: boolean) => void
  onTap: () => void
  onHandOff: (leaving: HTMLElement, keyboard: boolean) => void
}

function ToastItem({ toast, target, expanded, front, hidden, paused, reduce, store, classNames, onMeasure, onDragChange, onTap, onHandOff }: ToastItemProps) {
  const { id } = toast
  const [isPresent, safeToRemove] = usePresence()
  const itemRef = useRef<HTMLLIElement>(null)
  const contentRef = useRef<HTMLDivElement>(null)
  const actionRef = useRef<HTMLDivElement>(null)
  const closeRef = useRef<HTMLButtonElement>(null)
  const y = useMotionValue(0)
  const scale = useMotionValue(1)
  const height = useMotionValue(0)
  const opacity = useMotionValue(0)
  const contentOpacity = useMotionValue(1)
  const x = useMotionValue(0)
  const swipeFade = useTransform(x, (value) => (value > 0 ? 1 - Math.min(value / SWIPE_FADE, 1) * 0.75 : 1))
  const applied = useRef<boolean | null>(null)
  const swiped = useRef(false)
  const remaining = useRef(toast.duration)
  const gesture = useRef<Gesture | null>(null)
  const suppressClick = useRef(false)
  const pointerType = useRef("mouse")

  useLayoutEffect(() => {
    const node = contentRef.current
    if (!node) return
    onMeasure(id, node.offsetHeight + BORDER)
    if (typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(() => onMeasure(id, node.offsetHeight + BORDER))
    observer.observe(node)
    return () => observer.disconnect()
  }, [id, onMeasure])

  useLayoutEffect(() => {
    if (!isPresent || target.height <= 0) return
    const entering = applied.current === null
    const morph = !entering && applied.current !== expanded
    applied.current = expanded
    if (reduce) {
      y.jump(target.y)
      scale.jump(target.scale)
      height.jump(target.height)
      animate(opacity, target.opacity, reducedFade)
      animate(contentOpacity, target.content, reducedFade)
      return
    }
    if (entering) {
      y.jump(target.y + target.height)
      scale.jump(target.scale)
      height.jump(target.height)
      contentOpacity.jump(target.content)
      opacity.jump(0)
    }
    const spring = morph ? motionPresets.spring.morph : motionPresets.spring.smooth
    animate(y, target.y, spring)
    animate(scale, target.scale, spring)
    if (!entering) animate(height, target.height, spring)
    animate(opacity, target.opacity, entering ? enterFade : fade)
    animate(contentOpacity, target.content, fade)
  }, [contentOpacity, expanded, height, isPresent, opacity, reduce, scale, target.content, target.height, target.opacity, target.scale, target.y, y])

  useEffect(() => {
    remaining.current = toast.duration
  }, [toast.version, toast.duration])
  useEffect(() => {
    if (!isPresent || paused || !Number.isFinite(remaining.current) || toast.duration <= 0) return
    const started = performance.now()
    const timer = window.setTimeout(() => store.dismiss(id), Math.max(remaining.current, 0))
    return () => {
      window.clearTimeout(timer)
      remaining.current -= performance.now() - started
    }
  }, [id, isPresent, paused, store, toast.version, toast.duration])

  useEffect(() => {
    if (isPresent) return
    const node = itemRef.current
    if (node) {
      const active = document.activeElement
      if (active instanceof HTMLElement && node.contains(active)) onHandOff(node, focusVisible(active))
      node.setAttribute("inert", "")
    }
    const done = () => safeToRemove?.()
    if (reduce) {
      void animate(opacity, 0, reducedFade).then(done)
      return
    }
    if (!swiped.current) {
      animate(y, y.get() + 10, motionPresets.spring.smooth)
      animate(scale, scale.get() * 0.96, motionPresets.spring.smooth)
    }
    void animate(opacity, 0, { duration: swiped.current ? 0.22 : motionPresets.duration.exit, ease: standard }).then(done)
  }, [isPresent, onHandOff, opacity, reduce, safeToRemove, scale, y])

  function onPointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    pointerType.current = event.pointerType
    suppressClick.current = false
    if (event.button !== 0 || !isPresent || (event.target as Element).closest("button, a")) return
    x.stop()
    gesture.current = { pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, origin: x.get(), active: false, samples: [] }
  }

  function onPointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    const current = gesture.current
    if (!current || current.pointerId !== event.pointerId) return
    if (!current.active) {
      const dx = event.clientX - current.startX
      const dy = event.clientY - current.startY
      if (Math.hypot(dx, dy) < 6) return
      if (Math.abs(dy) > Math.abs(dx)) {
        gesture.current = null
        return
      }
      current.active = true
      current.startX = event.clientX
      suppressClick.current = true
      event.currentTarget.setPointerCapture(event.pointerId)
      event.currentTarget.dataset.dragging = ""
      window.getSelection()?.removeAllRanges()
      onDragChange(true)
    }
    const raw = current.origin + event.clientX - current.startX
    x.set(raw >= 0 ? raw : -rubberBand(-raw, event.currentTarget.offsetWidth))
    current.samples.push({ t: event.timeStamp, x: raw })
    while (current.samples.length > 2 && event.timeStamp - current.samples[0].t > 100) current.samples.shift()
  }

  function onPointerEnd(event: ReactPointerEvent<HTMLDivElement>, cancelled: boolean) {
    const current = gesture.current
    if (!current || current.pointerId !== event.pointerId) return
    gesture.current = null
    if (!current.active) return
    delete event.currentTarget.dataset.dragging
    onDragChange(false)
    const first = current.samples[0]
    const last = current.samples[current.samples.length - 1]
    const velocity = cancelled || !first || !last || last.t === first.t || event.timeStamp - last.t > 60 ? 0 : ((last.x - first.x) / (last.t - first.t)) * 1000
    const width = event.currentTarget.offsetWidth
    const offset = x.get()
    if (!cancelled && offset > 0 && velocity > -200 && offset + project(velocity) > width * 0.4) {
      swiped.current = true
      if (!reduce) animate(x, width + 40, { type: "spring", visualDuration: 0.32, bounce: 0, velocity: Math.max(velocity, 0) })
      store.dismiss(id)
      return
    }
    if (reduce) x.jump(0)
    else animate(x, 0, { ...motionPresets.spring.snappy, velocity: offset < 0 ? velocity * 0.3 : velocity })
  }

  function onCardClick(event: MouseEvent<HTMLDivElement>) {
    if (suppressClick.current) {
      suppressClick.current = false
      return
    }
    if (pointerType.current !== "mouse" && !(event.target as Element).closest("button, a")) onTap()
  }

  function runAction(event: MouseEvent<HTMLButtonElement>) {
    const keyboard = focusVisible(event.currentTarget)
    store.runAction(id)
    if (keyboard && !store.getSnapshot().find((item) => item.id === id)?.action) closeRef.current?.focus()
  }

  function onKeyDown(event: KeyboardEvent<HTMLLIElement>) {
    if (event.key !== "Escape") return
    event.stopPropagation()
    store.dismiss(id)
  }

  const markMoving = (moving: boolean) => {
    if (actionRef.current) actionRef.current.dataset.moving = moving ? "true" : "false"
  }
  const Icon = toast.type === "loading" ? null : icons[toast.type]
  const swap = reduce ? fadeOnly : textSwap

  return (
    <motion.li ref={itemRef} data-slot="toast-stack-item" role={toast.appearance === "undo" ? "status" : undefined} className={cn("absolute inset-x-0 bottom-0 origin-top", classNames?.item)} style={{ y, scale, height, opacity, zIndex: toast.seq }} data-front={front} data-expanded={expanded} inert={hidden} onKeyDown={onKeyDown}>
      <motion.div
        data-slot="toast-stack-card"
        data-appearance={toast.appearance}
        className={cn(
          "@container absolute inset-0 overflow-hidden rounded-xl border border-border bg-popover text-foreground shadow-md touch-pan-y data-[dragging]:cursor-grabbing data-[dragging]:select-none",
          !front && !expanded && "bg-muted",
          (front || expanded) && "shadow-lg",
          toast.appearance === "undo" && "rounded-full border-transparent bg-primary text-primary-foreground",
          classNames?.card,
        )}
        style={{ x, opacity: swipeFade }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={(event) => onPointerEnd(event, false)}
        onPointerCancel={(event) => onPointerEnd(event, true)}
        onClick={onCardClick}
      >
        <motion.div ref={contentRef} className="flex items-start gap-3 py-3 pr-3 pl-4" style={{ opacity: contentOpacity }}>
          <span className={cn("relative grid h-5 w-[18px] shrink-0 place-items-center text-muted-foreground", typeColor[toast.type])} aria-hidden="true">
            <AnimatePresence mode="popLayout" initial={false}>
              <Swap key={toast.type} className="col-start-1 row-start-1 grid place-items-center" {...(reduce ? fadeOnly : iconSwap)}>
                {Icon ? <Icon width={18} height={18} strokeWidth={1.75} /> : <span className="block size-4 animate-spin rounded-full border-2 border-current border-r-transparent motion-reduce:animate-none" />}
              </Swap>
            </AnimatePresence>
          </span>
          <div className="relative min-w-0 flex-1 text-sm leading-5">
            <span className="sr-only">{typeLabels[toast.type]}: </span>
            <span data-slot="toast-stack-title" className={cn("relative block font-medium", classNames?.title)}>
              <AnimatePresence mode="popLayout" initial={false}>
                <Swap key={toast.title} className="block" {...swap}>{toast.title}</Swap>
              </AnimatePresence>
            </span>
            <AnimatePresence mode="popLayout" initial={false}>
              {toast.description ? <Swap key={toast.description} data-slot="toast-stack-description" className={cn("mt-0.5 block", toast.appearance === "undo" ? "text-primary-foreground/80" : "text-muted-foreground", classNames?.description)} {...swap}>{toast.description}</Swap> : null}
            </AnimatePresence>
          </div>
          <AnimatePresence initial={false}>
            {toast.action ? (
              <motion.div
                key="action"
                ref={actionRef}
                className="-mt-1 flex shrink-0 justify-end data-[moving=true]:overflow-hidden @max-[21rem]:order-1 @max-[21rem]:mt-0 @max-[21rem]:basis-full @max-[21rem]:justify-start @max-[21rem]:pl-[calc(18px+0.75rem)]"
                initial={reduce ? { opacity: 0 } : { width: 0, opacity: 0 }}
                animate={{ width: "auto", opacity: 1 }}
                exit={reduce ? { opacity: 0 } : { width: 0, opacity: 0 }}
                transition={reduce ? reducedFade : { width: motionPresets.spring.smooth, opacity: fade }}
                onAnimationStart={() => markMoving(true)}
                onAnimationComplete={() => markMoving(false)}
              >
                <Button type="button" variant={toast.appearance === "undo" ? "ghost" : "outline"} size="sm" className={cn("h-7 rounded-full", toast.appearance === "undo" && "text-primary-foreground hover:bg-primary-foreground/10", classNames?.action)} onClick={runAction}>{toast.action.label}</Button>
              </motion.div>
            ) : null}
          </AnimatePresence>
                <Button ref={closeRef} type="button" variant="ghost" size="icon-sm" className={cn("-mt-1 -mr-0.5 size-7 rounded-full", toast.appearance === "undo" ? "text-primary-foreground" : "text-muted-foreground", classNames?.close)} aria-label="Dismiss notification" onClick={() => store.dismiss(id)}>
            <X width={16} height={16} strokeWidth={1.75} aria-hidden="true" />
          </Button>
        </motion.div>
      </motion.div>
    </motion.li>
  )
}

const positionClass = {
  "bottom-right": "right-6 max-[30rem]:right-0 max-[30rem]:left-0 max-[30rem]:mx-auto",
  "bottom-left": "left-6 max-[30rem]:right-0 max-[30rem]:left-0 max-[30rem]:mx-auto",
  "bottom-center": "inset-x-0 mx-auto",
}

export function ToastStack({ label = "Notifications", position = "bottom-right", contained = false, visibleToasts = 3, hotkey = true, className, classNames }: ToastStackProps) {
  const store = useStore()
  const toasts = useSyncExternalStore(store.subscribe, store.getSnapshot, getServerSnapshot)
  const reduce = !!useReducedMotion()
  const pageHidden = useSyncExternalStore(subscribeVisibility, () => document.visibilityState === "hidden", () => false)
  const [hovered, setHovered] = useState(false)
  const [focused, setFocused] = useState(false)
  const [tapped, setTapped] = useState(false)
  const [dragging, setDragging] = useState(false)
  const [heights, setHeights] = useState<Record<string, number>>({})
  const regionRef = useRef<HTMLElement>(null)
  const listRef = useRef<HTMLOListElement>(null)
  const returnFocus = useRef<HTMLElement | null>(null)
  if (tapped && toasts.length === 0) setTapped(false)
  const expanded = toasts.length > 0 && (hovered || focused || tapped)
  const paused = expanded || dragging || pageHidden

  const measure = useCallback((id: string, height: number) => setHeights((current) => (current[id] === height ? current : { ...current, [id]: height })), [])
  const prune = useCallback(() => setHeights((current) => Object.fromEntries(store.getSnapshot().filter((item) => item.id in current).map((item) => [item.id, current[item.id]]))), [store])
  const toggleTap = useCallback(() => setTapped((open) => !open), [])

  const handOff = useCallback((leaving: HTMLElement, keyboard: boolean) => {
    const items = Array.from(listRef.current?.children ?? []) as HTMLElement[]
    const at = items.indexOf(leaving)
    const candidates = items.filter((item) => item !== leaving && !item.hasAttribute("inert"))
    const next = candidates.find((item) => items.indexOf(item) > at) ?? candidates[candidates.length - 1]
    const button = next?.querySelector<HTMLElement>("button")
    if (keyboard && button) button.focus()
    else if (keyboard && returnFocus.current?.isConnected) returnFocus.current.focus()
    else (document.activeElement as HTMLElement | null)?.blur()
  }, [])

  useEffect(() => {
    if (!hotkey) return
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (!event.altKey || event.metaKey || event.ctrlKey || event.code !== "KeyT") return
      const target = listRef.current?.querySelector<HTMLElement>(":scope > li:not([inert]) button")
      if (!target) return
      event.preventDefault()
      target.focus({ focusVisible: true } as FocusOptions)
      setFocused(true)
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [hotkey])

  useEffect(() => {
    if (!tapped) return
    const onDown = (event: PointerEvent) => {
      if (!regionRef.current?.contains(event.target as Node)) setTapped(false)
    }
    document.addEventListener("pointerdown", onDown)
    return () => document.removeEventListener("pointerdown", onDown)
  }, [tapped])

  const { targets, listHeight } = layoutStack(toasts, heights, expanded, visibleToasts)

  function onFocus(event: FocusEvent<HTMLElement>) {
    const from = event.relatedTarget
    if (!(from instanceof Node) || !event.currentTarget.contains(from)) returnFocus.current = from instanceof HTMLElement ? from : null
    if (focusVisible(event.target)) setFocused(true)
  }

  function onBlur(event: FocusEvent<HTMLElement>) {
    if (!(event.relatedTarget instanceof Node) || !event.currentTarget.contains(event.relatedTarget)) setFocused(false)
  }

  return (
    <section
      ref={regionRef}
      data-slot="toast-stack"
      className={cn("pointer-events-none fixed bottom-6 z-[60] w-[min(22.5rem,calc(100%-2rem))] max-[30rem]:bottom-4", contained && "absolute bottom-4 z-[2]", positionClass[position], contained && position === "bottom-right" && "right-4 max-[30rem]:right-4 max-[30rem]:left-auto", contained && position === "bottom-left" && "left-4 max-[30rem]:left-4 max-[30rem]:right-auto", className, classNames?.root)}
      aria-label={hotkey ? `${label} (Alt+T)` : label}
      aria-live="polite"
      aria-relevant="additions text"
      aria-atomic="false"
      onFocus={onFocus}
      onBlur={onBlur}
    >
      <ol
        ref={listRef}
        data-slot="toast-stack-list"
        className={cn("pointer-events-auto relative m-0 list-none p-0", classNames?.list)}
        style={{ height: listHeight }}
        data-expanded={expanded}
        onPointerEnter={(event) => {
          if (event.pointerType === "mouse") setHovered(true)
        }}
        onPointerMove={(event) => {
          if (event.pointerType === "mouse" && !hovered) setHovered(true)
        }}
        onPointerLeave={(event) => {
          if (event.pointerType === "mouse") setHovered(false)
        }}
      >
        <AnimatePresence onExitComplete={prune}>
          {toasts.map((item, index) => (
            <ToastItem key={item.id} toast={item} target={targets[index]} expanded={expanded} front={index === 0} hidden={index >= visibleToasts} paused={paused} reduce={reduce} store={store} classNames={classNames} onMeasure={measure} onDragChange={setDragging} onTap={toggleTap} onHandOff={handOff} />
          ))}
        </AnimatePresence>
      </ol>
    </section>
  )
}

